#!/bin/bash
# Renders FILE.j2 into FILE, next to it, for this node: the second pass of a file the
# container VMs share. The template gets the node's inv.host_vars (tools/inventory.py):
#   node:     the node name, which is the hostname
#   services: its inventory services, e.g. services.traefik.subdomain
#   addr:     its containers' IP addresses, e.g. addr.traefik
# Usage:
#   src/base/podman/render_host.sh FILE
# Ref:
# https://github.com/kpfleming/jinjanator

# shellcheck source=src/base/lib.sh
source "$(dirname "${BASH_SOURCE[0]}")/../../base/lib.sh"

file=${1:?usage: $0 FILE}
rm -f "$file"

if [ ! -f "$file.j2" ]; then
  die "file template $file.j2 does not exist"
fi

case $(hostname -s) in
  homesvcs)
    vars='{"addr": {"crowdsec_appsec": "10.12.0.23", "fluentbit": "10.12.0.20", "home_assistant": "10.12.0.11", "mosquitto": "10.12.0.8", "traefik": "10.12.0.6", "vmagent": "10.12.0.7", "zigbee2mqtt": "10.12.0.9"}, "node": "homesvcs", "services": {"crowdsec_appsec": {"dirs": ["services/crowdsec"], "ip": 23, "shared": true, "upstream": "docker.io/crowdsecurity/crowdsec:latest"}, "fluentbit": {"ip": 20, "shared": true, "upstream": "docker.io/fluent/fluent-bit:5.1"}, "home_assistant": {"ip": 11, "subdomain": "home", "upstream": "docker.io/homeassistant/home-assistant:2026.10", "uptime": "home assistant", "uptime_tier": 1}, "mosquitto": {"ip": 8, "upstream": "docker.io/library/eclipse-mosquitto:latest"}, "traefik": {"admin": true, "ip": 6, "shared": true, "subdomain": "homeproxy", "upstream": "docker.io/library/traefik:v3.7", "uptime": "traefik homesvcs", "uptime_tier": 1}, "vmagent": {"dirs": ["services/victoriametrics"], "ip": 7, "shared": true, "upstream": "docker.io/victoriametrics/vmagent:latest"}, "zigbee2mqtt": {"ip": 9, "subdomain": "zigbee", "upstream": "ghcr.io/koenkk/zigbee2mqtt:latest", "uptime": "zigbee2mqtt"}}}'
    ;;
  secsvcs)
    vars='{"addr": {"alertmanager": "10.10.0.10", "authelia": "10.10.0.5", "crowdsec": "10.10.0.16", "crowdsec_appsec": "10.10.0.23", "fluentbit": "10.10.0.20", "gatus": "10.10.0.9", "grafana": "10.10.0.12", "lldap": "10.10.0.4", "ntfy": "10.10.0.13", "ntfy-alertmanager": "10.10.0.14", "ntfy_idp_push": "10.10.0.18", "olive_tin": "10.10.0.15", "postgres": "10.10.0.3", "traefik": "10.10.0.6", "vaultwarden": "10.10.0.17", "victorialogs": "10.10.0.8", "victoriametrics": "10.10.0.7", "vmalert": "10.10.0.11"}, "node": "secsvcs", "services": {"alertmanager": {"admin": true, "ip": 10, "subdomain": "alert", "update_last": true, "upstream": "docker.io/prom/alertmanager:latest", "uptime": "alertmanager"}, "authelia": {"ip": 5, "subdomain": "auth", "upstream": "docker.io/authelia/authelia:4.39", "uptime": "authelia", "uptime_conditions": ["[BODY].status == OK"], "uptime_path": "/api/health", "uptime_tier": 1}, "crowdsec": {"ip": 16, "upstream": "docker.io/crowdsecurity/crowdsec:latest"}, "crowdsec_appsec": {"dirs": ["services/crowdsec"], "ip": 23, "shared": true, "upstream": "docker.io/crowdsecurity/crowdsec:latest"}, "fluentbit": {"ip": 20, "shared": true, "upstream": "docker.io/fluent/fluent-bit:5.1"}, "gatus": {"ip": 9, "subdomain": "uptime", "upstream": "docker.io/twinproduction/gatus:latest"}, "grafana": {"ip": 12, "subdomain": "graph", "upstream": "docker.io/grafana/grafana-oss:latest", "uptime": "grafana", "uptime_tier": 1}, "lldap": {"admin": true, "ip": 4, "subdomain": "ldap", "upstream": "docker.io/lldap/lldap:stable"}, "ntfy": {"ip": 13, "subdomain": "push", "update_last": true, "upstream": "docker.io/binwiederhier/ntfy:latest", "uptime": "ntfy health check", "uptime_path": "/v1/health", "uptime_tier": 1}, "ntfy-alertmanager": {"dirs": ["services/alertmanager"], "ip": 14, "subdomain": "ntfy-alertmanager", "update_last": true, "upstream": "docker.io/xenrox/ntfy-alertmanager:latest"}, "ntfy_idp_push": {"admin": true, "ip": 18, "subdomain": "idp-push", "upstream": "ghcr.io/babraham123/ntfy-idp-push:latest", "uptime": "ntfy-idp-push", "uptime_path": "/healthz"}, "olive_tin": {"admin": true, "ip": 15, "subdomain": "command", "upstream": "docker.io/jamesread/olivetin:latest-3k", "uptime": "olive_tin"}, "postgres": {"ip": 3, "upstream": "docker.io/library/postgres:18-alpine"}, "traefik": {"admin": true, "ip": 6, "shared": true, "subdomain": "secproxy", "update_last": true, "upstream": "docker.io/library/traefik:v3.7", "uptime": "traefik secsvcs", "uptime_tier": 1}, "vaultwarden": {"admin": true, "ip": 17, "subdomain": "vault", "upstream": "docker.io/vaultwarden/server:latest", "uptime": "vaultwarden", "uptime_path": "/alive", "uptime_tier": 1}, "victorialogs": {"ip": 8, "subdomain": "logs", "upstream": "docker.io/victoriametrics/victoria-logs:latest", "uptime": "victorialogs"}, "victoriametrics": {"ip": 7, "subdomain": "metrics", "update_last": true, "upstream": "docker.io/victoriametrics/victoria-metrics:latest", "uptime": "victoriametrics"}, "vmalert": {"admin": true, "ip": 11, "subdomain": "vmalert", "update_last": true, "upstream": "docker.io/victoriametrics/vmalert:latest", "uptime": "vmalert"}}}'
    ;;
  vpnsvcs)
    vars='{"addr": {"fluentbit": "10.13.0.20", "geoip_generator": "10.13.0.30", "vmagent": "10.13.0.7"}, "node": "vpnsvcs", "services": {"crowdsec_firewall_bouncer": {"dirs": ["services/crowdsec"]}, "deadman": {}, "fail2ban": {}, "fluentbit": {"ip": 20, "shared": true, "upstream": "docker.io/fluent/fluent-bit:5.1"}, "geoip_generator": {"build": "geoip_generator", "ip": 30}, "haproxy": {}, "headscale": {}, "tailscaled": {}, "vmagent": {"dirs": ["services/victoriametrics"], "ip": 7, "shared": true, "upstream": "docker.io/victoriametrics/vmagent:latest"}}}'
    ;;
  websvcs)
    vars='{"addr": {"bookmark_handoff": "10.11.0.24", "calliope": "10.11.0.22", "car_ingest": "10.11.0.26", "copyparty": "10.11.0.19", "crowdsec_appsec": "10.11.0.23", "finance_exporter": "10.11.0.50", "fluentbit": "10.11.0.20", "homepage": "10.11.0.9", "isso": "10.11.0.10", "linkding": "10.11.0.17", "nginx": "10.11.0.8", "readeck": "10.11.0.18", "storyteller": "10.11.0.21", "traefik": "10.11.0.6", "vmagent": "10.11.0.7", "yt_to_audiobook": "10.11.0.25"}, "node": "websvcs", "services": {"bookmark_handoff": {"build": "bookmark_handoff", "ip": 24}, "calliope": {"build": "calliope", "ip": 22}, "car_ingest": {"build": "car_ingest", "ip": 26}, "copyparty": {"ip": 19, "subdomain": "files", "upstream": "docker.io/copyparty/ac:latest", "uptime": "copyparty"}, "crowdsec_appsec": {"dirs": ["services/crowdsec"], "ip": 23, "shared": true, "upstream": "docker.io/crowdsecurity/crowdsec:latest"}, "finance_exporter": {"build": "finance_exporter", "ip": 50}, "fluentbit": {"ip": 20, "shared": true, "upstream": "docker.io/fluent/fluent-bit:5.1"}, "homepage": {"ip": 9, "subdomain": "dash", "upstream": "ghcr.io/gethomepage/homepage:latest", "uptime": "homepage", "uptime_tier": 1}, "isso": {"ip": 10, "subdomain": "comment", "upstream": "ghcr.io/isso-comments/isso:release"}, "linkding": {"ip": 17, "subdomain": "archive", "upstream": "docker.io/sissbruecker/linkding:latest-plus", "uptime": "linkding", "uptime_path": "/health"}, "nginx": {"ip": 8, "subdomain": "www", "upstream": "docker.io/library/nginx:stable"}, "readeck": {"ip": 18, "subdomain": "read", "upstream": "codeberg.org/readeck/readeck:latest", "uptime": "readeck", "uptime_path": "/api/info"}, "snapraid": {}, "storyteller": {"ip": 21, "subdomain": "books", "upstream": "registry.gitlab.com/storyteller-platform/storyteller:web-v3.0.0-beta", "uptime": "storyteller", "uptime_path": "/api/health"}, "traefik": {"admin": true, "ip": 6, "shared": true, "subdomain": "webproxy", "upstream": "docker.io/library/traefik:v3.7", "uptime": "traefik websvcs", "uptime_tier": 1}, "vmagent": {"dirs": ["services/victoriametrics"], "ip": 7, "shared": true, "upstream": "docker.io/victoriametrics/vmagent:latest"}, "yt_to_audiobook": {"build": "yt_to_audiobook", "ip": 25}}}'
    ;;
esac

echo "$vars" | jinjanate --quiet --format=json -o "$file" "$file.j2"
